#!/usr/bin/env python3
"""build_armP_histories.py — build + gate armP_histories_v1.json (arm P frozen inputs).

REPLAY histories = verbatim trimmed A-answers from the grid (turns 1..11 per ordering).
PARA histories   = same semantics, surface rewritten. Authored by Claude (Anthropic) —
                   deliberately a different vendor from the subject model, mirroring the
                   judge discipline; logged here as the authorship note of record.

Authoring rules (gated below at word level; token-level re-gate runs on the box with
llama-tokenize before any capture):
  R1 no shared word-6-gram (case/punct-normalized) between a paraphrase and ANY original
     answer of the same ordering  (6-word runs under-approximate token 8-grams)
  R2 no shared word-6-gram between any TWO paraphrases of the same ordering
     (a repeated run inside the history would itself be copy material)
  R3 word count within +/-10% of the original turn  (context-length control;
     box gate: token count within +/-10% via llama-tokenize)
  R4 probes are IDENTICAL between replay and para conditions (only assistant text moves)
"""
import json, pathlib, re, sys

HERE = pathlib.Path(__file__).resolve().parent
trans = json.loads((HERE / "pulled/convdyn_grid/transcripts.json").read_text())

def turns(o, upto=11):
    return [e for e in trans[f"A_o{o}"] if e["turn"] <= upto]

def probe_at(o, k):
    return next(e["probe"] for e in trans[f"A_o{o}"] if e["turn"] == k)

