# ---------------- gates ----------------
def norm_words(s):
    return re.findall(r"[a-z0-9']+", s.lower())

def grams(ws, n=6):
    return {tuple(ws[i:i+n]) for i in range(len(ws) - n + 1)}

fail = []
out = {"meta": {
        "version": "v1", "date": "2026-07-02",
        "source": "pulled/convdyn_grid/transcripts.json (arm A trimmed responses, turns 1..11)",
        "authorship": "Paraphrases authored by Claude (Anthropic) — different vendor from the subject model, per judge discipline. Semantics preserved per turn; surface fully rewritten.",
        "gates_local": "R1/R2 no shared word-6-gram (normalized) para-vs-originals and para-vs-para within ordering; R3 word count +/-10%",
        "gates_box": "llama-tokenize: token count +/-10% per turn; no shared token-8-gram para-vs-original (capture-blocking)",
        "k_values": [4, 8, 12], "note": "probes identical between conditions (R4); replay text verbatim incl. trim artifacts"}}
for o in (1, 2, 3):
    key = f"o{o}"
    ents = turns(o)
    orig_ws = {e["turn"]: norm_words(e["response_trimmed"]) for e in ents}
    para_ws = {t: norm_words(PARA[key][t]) for t in PARA[key]}
    all_orig_grams = set().union(*[grams(w) for w in orig_ws.values()])
    for t, pws in para_ws.items():
        pg = grams(pws)
        hit = pg & all_orig_grams
        if hit: fail.append(f"{key} t{t} R1 shares {len(hit)} 6-grams with originals e.g. {' '.join(list(hit)[0])!r}")
        lo, hi = 0.9 * len(orig_ws[t]), 1.1 * len(orig_ws[t])
        if not (lo <= len(pws) <= hi):
            fail.append(f"{key} t{t} R3 words {len(pws)} outside [{lo:.0f},{hi:.0f}] (orig {len(orig_ws[t])})")
    ts = sorted(para_ws)
    for i, t1 in enumerate(ts):
        for t2 in ts[i+1:]:
            hit = grams(para_ws[t1]) & grams(para_ws[t2])
            if hit: fail.append(f"{key} t{t1}~t{t2} R2 share {len(hit)} 6-grams e.g. {' '.join(list(hit)[0])!r}")
    out[key] = {
        "probes": {str(k): probe_at(o, k) for k in (4, 8, 12)},
        "replay": [{"turn": e["turn"], "slot": e["slot"], "probe": e["probe"], "text": e["response_trimmed"]} for e in ents],
        "para":   [{"turn": e["turn"], "slot": e["slot"], "probe": e["probe"], "text": PARA[key][e["turn"]]} for e in ents],
    }

if fail:
    print("GATE FAILURES:"); [print(" -", f) for f in fail]; sys.exit(1)
p = HERE / "armP_histories_v1.json"
p.write_text(json.dumps(out, indent=1, ensure_ascii=False))
import hashlib
print(f"ALL GATES PASS -> {p}")
print("sha256:", hashlib.sha256(p.read_bytes()).hexdigest())
